-- Tipos reales encontrados en el Excel. No elimina los catalogos anteriores.
INSERT dbo.tipos_vehiculo(nombre)
SELECT DISTINCT LTRIM(RTRIM(f.tipo)) FROM #FuenteParque f
WHERE NOT EXISTS(SELECT 1 FROM dbo.tipos_vehiculo t WHERE UPPER(LTRIM(RTRIM(t.nombre)))=UPPER(LTRIM(RTRIM(f.tipo))));
-- Dependencias e instituciones del Excel, asociadas a la organizacion 1.
INSERT dbo.dependencias(organization_id,nombre,activo)
SELECT @OrganizationId,LTRIM(RTRIM(f.dependencia)),1 FROM #FuenteParque f
WHERE NULLIF(LTRIM(RTRIM(f.dependencia)),N'') IS NOT NULL
AND NOT EXISTS(SELECT 1 FROM dbo.dependencias d WHERE d.organization_id=@OrganizationId AND UPPER(LTRIM(RTRIM(d.nombre)))=UPPER(LTRIM(RTRIM(f.dependencia))))
GROUP BY LTRIM(RTRIM(f.dependencia));
-- Tipos de documento. Se usan nombres ASCII para evitar dependencias de codificacion.
INSERT dbo.tipos_documento(nombre,obligatorio,dias_alerta_default)
SELECT x.nombre,1,45 FROM(VALUES(N'SOAT'),(N'Tecnomecanica'),(N'Poliza'))x(nombre)
WHERE NOT EXISTS(SELECT 1 FROM dbo.tipos_documento t WHERE UPPER(t.nombre)=UPPER(x.nombre));
-- Mapeo: ACTIVO=>Activo, REPOSO=>En reposo, A CARGO DEL COMODATARIO=>En comodato.
INSERT dbo.vehiculos(organization_id,placa,tipo_vehiculo_id,marca,modelo,dependencia_id,estado_id,observaciones,activo)
SELECT @OrganizationId,UPPER(LTRIM(RTRIM(f.placa))),t.id,NULLIF(LTRIM(RTRIM(f.marca)),N''),TRY_CONVERT(int,NULLIF(LTRIM(RTRIM(f.modelo)),N'')),d.id,e.id,
CONCAT(CASE WHEN NULLIF(LTRIM(RTRIM(f.en_uso)),N'') IS NULL THEN N'' ELSE N'En uso: '+LTRIM(RTRIM(f.en_uso))+N'. ' END,CASE WHEN NULLIF(LTRIM(RTRIM(f.asignacion)),N'') IS NULL THEN N'' ELSE N'Asignacion: '+LTRIM(RTRIM(f.asignacion))+N'.' END),1
FROM #FuenteParque f JOIN dbo.tipos_vehiculo t ON UPPER(LTRIM(RTRIM(t.nombre)))=UPPER(LTRIM(RTRIM(f.tipo)))
JOIN dbo.estados_vehiculo e ON UPPER(e.nombre)=UPPER(CASE WHEN UPPER(f.estado)=N'ACTIVO' THEN N'Activo' WHEN UPPER(f.estado)=N'REPOSO' THEN N'En reposo' ELSE N'En comodato' END)
LEFT JOIN dbo.dependencias d ON d.organization_id=@OrganizationId AND UPPER(LTRIM(RTRIM(d.nombre)))=UPPER(LTRIM(RTRIM(f.dependencia)))
WHERE NOT EXISTS(SELECT 1 FROM dbo.vehiculos v WHERE v.organization_id=@OrganizationId AND UPPER(LTRIM(RTRIM(v.placa)))=UPPER(LTRIM(RTRIM(f.placa))));
-- Conserva cada vencimiento como version; el mas reciente por documento queda vigente.
;WITH F AS(SELECT f.placa,x.tipo,x.fecha FROM #FuenteParque f CROSS APPLY(VALUES(N'SOAT',f.soat25),(N'Tecnomecanica',f.tecno25),(N'Poliza',f.poliza25),(N'SOAT',f.soat26),(N'Tecnomecanica',f.tecno26),(N'Poliza',f.poliza26),(N'SOAT',f.soat27),(N'Tecnomecanica',f.tecno27),(N'Poliza',f.poliza27))x(tipo,fecha) WHERE x.fecha IS NOT NULL),V AS(SELECT placa,tipo,fecha,ROW_NUMBER() OVER(PARTITION BY placa,tipo ORDER BY fecha)version,MAX(fecha)OVER(PARTITION BY placa,tipo)ultima FROM F)
INSERT dbo.documentos(organization_id,vehiculo_id,tipo_documento_id,fecha_vencimiento,estado_documento,version,vigente_actual,observaciones)
SELECT @OrganizationId,v.id,t.id,x.fecha,CASE WHEN x.fecha<CONVERT(date,GETDATE()) THEN N'Vencido' WHEN x.fecha<=DATEADD(day,45,CONVERT(date,GETDATE())) THEN N'Proximo_a_vencer' ELSE N'Vigente' END,x.version,CASE WHEN x.fecha=x.ultima THEN 1 ELSE 0 END,N'Importado desde PARQUE AUTOMOTOR.xlsx.'
FROM V x JOIN dbo.vehiculos v ON v.organization_id=@OrganizationId AND UPPER(LTRIM(RTRIM(v.placa)))=UPPER(LTRIM(RTRIM(x.placa))) JOIN dbo.tipos_documento t ON UPPER(t.nombre)=UPPER(x.tipo)
WHERE NOT EXISTS(SELECT 1 FROM dbo.documentos d WHERE d.vehiculo_id=v.id AND d.tipo_documento_id=t.id AND d.fecha_vencimiento=x.fecha);
SELECT N'Vehiculos' concepto,COUNT(*) cantidad FROM dbo.vehiculos WHERE organization_id=@OrganizationId
UNION ALL SELECT N'Documentos',COUNT(*) FROM dbo.documentos WHERE organization_id=@OrganizationId
UNION ALL SELECT N'Dependencias',COUNT(*) FROM dbo.dependencias WHERE organization_id=@OrganizationId;
IF @ModoPrueba=1 BEGIN ROLLBACK;PRINT 'SIMULACION TERMINADA. No se guardaron cambios.';END ELSE BEGIN COMMIT;PRINT 'CARGA CONFIRMADA.';END;


